INSERT INTO "arena_testing_scenarios" ("id","name","group","description","source") VALUES
('family-01-awaken','Awaken and alternate Awaken','family','Exact Life/board threshold; correct face, draws and energy switches; wrong threshold refuses. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-02-energy-costs','Energy and specified costs','family','Correct colored orbs, generic energy and alternative payments; no partial spending on failure. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-03-optional-exact','Optional exact-count selection','family','BT3-109 five Warp cards, BT6-062/SD8-03 two hand cards; all required cards or decline, never partial payment. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-04-bond','Bond','family','XD1-05 with one/two matching Universe 6 Battle Cards; Extras do not count; condition rechecked and real energy price retained. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-05-attack-revenge','Native multiple attacks and Revenge','family','BT27-093 Triple Attack gives exactly three attacks; BT7-081 Revenge KOs at the correct battle timing. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-06-damage-blocker','Strike, Critical and Blocker','family','Correct Life damage destinations/count; legal blocker timing; attacking player''s resource gain differs after ordinary damage. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-07-counter-chains','Counter windows and chains','family','Counter: Attack/Play/Counter eligibility, paid costs, decline and nested resolution order. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-08-protection','Barrier, Deflect and protection','family','Target selection versus non-targeting effects; protected and unprotected windows distinguished. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-09-auto-limits','Auto timing and once-per-turn','family','Play/arrival/attack/KO timing; simultaneous ordering; limits shared or per-copy as printed. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-10-hidden-autos','Hidden-area Autos','family','Reveal only when required; decline safely; no opponent-visible hidden choices or metadata. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-11-condition-price','Condition versus price','family','SD13-05 stored condition metadata; true/false condition, actual price, preserved owner-authored effect. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-12-evolve','Evolve and EX-Evolve','family','Correct base, cost, stacked cards and evolved-into triggers; ordinary play is not Evolve. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-13-combo-end-evolve','Combo-end Great Ape evolution','family','BT3-098/BT3-096 from hand and Battle combos; own turn, actual Drop cleanup, then Evolve and payoff. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-14-union-materials','Union-Fusion and Union-Potara','family','Exact material names/power/areas; material destination, legal play and generated movement triggers. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-15-over-realm-warp','Over Realm and Warp movement','family','Threshold, payment, turn restriction and cleanup; BT3-112 self trigger from Battle/deck to Warp. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-16-absorb-stacks','Union-Absorb and under-card stacks','family','Correct targets, stack order, inherited information and removal cleanup. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-17-swap-revive','Swap and Revive','family','Correct returned/played cards, replacement windows and cost order; failed payment gives no play. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-18-wish-desire','Wish/Desire and World Peace','family','Dragon Ball condition; World Peace energy cost at most three, independent of current energy count. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-19-unison-spirit-boost','Unison and Spirit Boost','family','Specified cost, starting/changed markers, activation payment, battle damage and zero-marker removal. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-20-z-cards','Z-Energy, Z-Awaken and Z-Stack','family','Eligible combo cleanup to Z-Energy; exact Z payment, source/stack and zone transitions. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-21-aegis','Aegis and multicolor payments','family','Correct colors and alternate payment; costs before benefits; limited activations and failure rollback. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-22-movement-replacements','Replacements and original movement information','family','Cooler BT29-029 original Battle holder/color/trait; BT29-040 diverted hand return must not announce an actual hand return. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-23-grants-duration','Granted skills, negation and duration','family','Heroic/Villainous, gained skills and temporary traits; correct controller, expiry and interaction order. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('family-24-ai-ui-replay','AI decisions and UI/replay parity','family','Known lethal, avoidable loss, Life-to-hand resources, legal choices; same visible information, deterministic replay, clear browser prompts. Planned family: each actual card/face/skill still needs its own evidence mapping; a baseline proof does not pass the whole family.','docs/arena-deck-coverage-plan.md#small-scenario-build-list'),
('wc-r01','WC-R01 — Cell deck restriction','white_cell_rule','Cell Leader plus a non-white Extra in a deck list: report the printed deck restriction in legality; deck editing stays possible under the app''s “legality is a flag” rule. A white Extra passes that restriction. Evidence scope: Missing named rule-specific legality proof. Qualification must not be substituted for legality. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#twelve-minimal-rule-scenarios'),
('wc-r02','WC-R02 — Front selection and back Extra recovery','white_cell_rule','Front Leader Main skill: offer only white Cell cards in deck; choose none or exactly one, move that copy to Drop, shuffle, prohibit another use that turn. Back Main/Battle recovery: only white cost-2 Extras with Main/Battle skill in Drop, choose none or one, once per turn across both windows. Evidence scope: Missing complete real-Leader front/back scenarios. Generic selection/once-per-turn evidence exists. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#twelve-minimal-rule-scenarios'),
('wc-r03','WC-R03 — Awaken threshold and Life output','white_cell_rule','Awaken with life 4 and insufficient Drop qualifies; life 8 with exactly 3 eligible Drop cards qualifies; life 8 with 2 does not. Resolve draw 2 and flip; life 8 becomes 6 by adding exactly 2 Life cards to hand, while life 4 is not increased or forced to move Life “up to 6.” Non-Cell white Battle cards do not count as Cells. Evidence scope: Missing complete real-card threshold/output proof. Reading helpers have generic grouped-condition coverage. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#twelve-minimal-rule-scenarios'),
('wc-r04','WC-R04 — Qualified play and current-cost capture','white_cell_rule','Back Leader trigger: white Cell/Cell Jr. at current cost ≥3 pends; wrong color/character/cost 2 does not. Freeze qualification at play before later Autos alter cost/area. A reduced payment is not automatically a reduced card cost: BT31-119''s discount applies in Z-Deck; after it enters Battle its own printed cost is 3, so a paid cost of 1 alone must not disqualify the trigger. Evidence scope: Existing core / partial real support: readings-571.ts, free-extra-680.ts test shared qualifications, current-cost capture, reduced costs and later changes on synthetic subjects. Add BT31-119''s actual zone-scoped discount. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#twelve-minimal-rule-scenarios'),
('wc-r05','WC-R05 — Hidden price and chosen Extra activation','white_cell_rule','Qualifying play, one Revealed energy and a white cost-2 Main/Battle Extra in hand. Decline Auto: no Hidden payment/Extra use. Accept: hide exactly one Revealed energy (Rested energy is eligible); optionally select one eligible Extra, activate its chosen skill without its original skill cost, move it to Drop, preserve Extra-activation watchers. Selecting no Extra after paying does not refund the Hidden cost. Already-Hidden energy cannot pay a change-to-Hidden action. Evidence scope: Existing core: free-extra-680.ts proves payment, optional hand selection, cost waiver, move-before-activation, watcher, invalid actor/target, JSON reload/privacy. arena-free-extra-db.mts adds saved revision/idempotency/privacy. Real five-Extra integration still needed. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#twelve-minimal-rule-scenarios'),
('wc-r06','WC-R06 — Regeneration and energy visibility','white_cell_rule','Invoke BT31-140 while an opponent card attacks: draw 1, choose 0–3 Hidden energy to reveal, +10000 Leader for this battle only. Own attack/Main use has no conditional Leader bonus. Each energy retains its previous Active/Rest state and restored White color is available only on Active energy. Evidence scope: Missing complete named Regeneration scenario; partial generic hidden.ts, effective-payment-colours-626.ts, battle-stakes-562.ts cover Hidden information/payment facts. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#twelve-minimal-rule-scenarios'),
('wc-r07','WC-R07 — Solar Flare and removal Autos','white_cell_rule','Invoke BT31-138 with a white Cell Battle Card and an opponent keyword-bearing card: independently choose up to one own Cell return and up to one opponent keyword negation. Negate the chosen keyword, not all skills; it returns after the turn. Return-by-skill should cause the printed BT31-129/130 removal Autos where appropriate; a KO is a distinct negative control for “by a skill.” Evidence scope: Missing named Solar Flare → Cell removal integration. Separate watcher/pick/negation families exist. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#twelve-minimal-rule-scenarios'),
('wc-r08','WC-R08 — Absorb, stack and granted Barrier','white_cell_rule','BT31-139: draw 1, choose a real white Cell Battle base, decline Android placement → no conditional stack play; accept one Android from Drop → put it under that base, then optionally play exactly one eligible white cost≤4 Cell from Drop on top Active. With BT31-130 underneath and a white Cell Leader, top gains Barrier; removing/invalidating the prerequisite removes that grant. Evidence scope: Missing complete Absorb/under-card Barrier scenario; partial generic stack/under-card mechanics and #542 integrity proof. It is a stack play, not an invented Evolve activation. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#twelve-minimal-rule-scenarios'),
('wc-r09','WC-R09 — Ominous Android reactive stack','white_cell_rule','BT31-131 from Drop: require white Cell Leader, energy count≥2 and one Revealed energy to hide; it enters Rested. On opponent''s turn only, with opponent energy≥2 and full {1} paid, its Battle skill may stack an eligible white cost-4 Cell from Drop onto it Active. Wrong turn/energy/area/cost does not qualify. Evidence scope: Missing named two-step Ominous Android scenario. Generic skill prices/play-on-top exist. Preserve source identity/counter continuation across reload. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#twelve-minimal-rule-scenarios'),
('wc-r10','WC-R10 — White EX-Evolve and bounded attacks','white_cell_rule','BT31-129 EX-Evolve: at least 3 energy, actual White orb plus printed draw-1 price, correct white Cell base cost≥3; use once under Limit 1. Stack according to Evolve rules. Dual Attack''s after-battle reactivation is bounded. Its attacking Auto reveals up to one energy without untapping it. On removal by skill, optionally play the exact eligible cost-4 Cell from Drop; ordinary battle KO does not satisfy that printed cause. Evidence scope: Partial: generic Evolve, Attack, price, cause and Hidden families; missing this real paid White chain and its combined follow-ups. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#twelve-minimal-rule-scenarios'),
('wc-r11','WC-R11 — Cell Jr. reactive play and Z-Energy','white_cell_rule','BT31-133 on opponent''s turn, white Leader, opponent energy≥2 and Hidden energy available: pay by revealing one, play from hand, choose up to one own card for +5000 this battle. Then its on-play draw precedes the required hand→Z-Energy choice (the drawn card can be chosen), skills negated for turn. Wrong turn/condition, no actual Hidden→Revealed change, or a skipped mandatory hand choice fails. Evidence scope: Missing complete real Cell Jr. reactive sequence. Generic combo/Z-Energy, mode prices and duration evidence is only partial. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#twelve-minimal-rule-scenarios'),
('wc-r12','WC-R12 — Ultimate Form end-turn reveal','white_cell_rule','BT31-128 successful play: draw 1, switch this Cell Active, optional KO, schedule all-energy Revealed for that turn''s end. Before end turn energy remains as currently Hidden/Revealed; at end all becomes Revealed while each Active/Rest status persists. Repeated continuation/reload performs the delayed effect once. Separate Evolve {1} and Main {2} play prices must remain distinct. Evidence scope: Missing named Ultimate Form resource-restoration scenario; partial generic delay, mode and evolution. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#twelve-minimal-rule-scenarios'),
('wc-a01','WC-A01 — Preserve Active White payment sources','white_cell_strategy','Pay the Leader''s Hide-energy price using an already-Rested Revealed energy when that preserves the sole Active White payment source for a known EX-Evolve/defensive option. Compare all legal payments and remaining affordable options; don''t treat Hidden/Revealed as an untap. Evidence scope: Missing White-specific benchmark. General policy color-preserving payments exist. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#seven-decision-benchmarks-strategy-not-engine-legality'),
('wc-a02','WC-A02 — Choose or decline a useful Extra','white_cell_strategy','Choose/decline the optional Leader Extra activation according to a concrete opportunity: safe recovery with Regeneration, useful removal/buff with Kamehameha, or pointless cost when no useful Extra can be activated. Record hand/card gain and future legal options, not “always pay.” Evidence scope: Missing, despite rules-proof coverage of pay/decline. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#seven-decision-benchmarks-strategy-not-engine-legality'),
('wc-a03','WC-A03 — Efficient defense and resource recovery','white_cell_strategy','During a threatening opponent attack, select Regeneration when its +10000 actually saves life and restoring color preserves later defense; compare Cell Jr.''s +5000 and available combos by actual card/energy expenditure. Include a battle where neither boost changes the result and conserving cards is preferable. Evidence scope: Missing White-specific; partial generic combat threshold/cheapest-defense benchmarks. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#seven-decision-benchmarks-strategy-not-engine-legality'),
('wc-a04','WC-A04 — Sequence discounted Cell development','white_cell_strategy','Sequence Hidden energy → discounted BT31-119 development → Leader Extra → reveal recovery when legal and useful. Score eligible board development, triggered Extra value, Z-Energy and retained Active White sources. Include a case where paying for the chain leaves an unavoidable lethal threat and should be avoided. Evidence scope: Missing chain benchmark; qualification is not sequence evidence. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#seven-decision-benchmarks-strategy-not-engine-legality'),
('wc-a05','WC-A05 — Evolution timing and protected bases','white_cell_strategy','Choose an EX-Evolve base and timing that preserves a valuable BT31-130 under-card Barrier grant and creates profitable bounded Dual Attack, versus retaining a necessary defender. Compare resulting board and battle value after the full opposing legal response fixture; never assume unseen counters absent. Evidence scope: Missing real White evolution strategy. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#seven-decision-benchmarks-strategy-not-engine-legality'),
('wc-a06','WC-A06 — Recover the right cost-2 Extra','white_cell_strategy','Recover the right cost-2 Extra with the back Leader''s once-per-turn Main/Battle skill: defense before lethal (Regeneration/Summon), pressure/removal on own turn (Kamehameha), or safe Cell recycling (Solar Flare). Respect timing/limit and legal concrete targets; score resulting saved life or removed threat, not merely card mana value. Evidence scope: Missing effect-aware recovery benchmark. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#seven-decision-benchmarks-strategy-not-engine-legality'),
('wc-a07','WC-A07 — Combo and reactive-play opportunity cost','white_cell_strategy','Use a 0-cost/5000 combo or Cell Jr. reactive play only when it changes the battle or preserves a higher-value hand/resource plan. Include Sparking-5 Android 18 draw and cell-evolution ingredients where their opportunity cost is explicit. Score cards spent, life saved/dealt, legal follow-up development and conserved White sources. Evidence scope: Partial generic efficient-combo policy tests; missing the White-card opportunity-cost fixtures. This complete checklist item starts planned; inspected component evidence is not an exact-revision pass for the item.','docs/arena-white-cell-validation.md#seven-decision-benchmarks-strategy-not-engine-legality'),
('ai-01','AI-01 — Proven lethal and Life-to-hand replenishment','strategy','Objective: take a legal line that wins against every response in the fixture''s declared response set when such a line exists. Acceptable actions are first steps of independently replayed winning lines, including bounded multiple attacks and any required combos; a projected lethal line that fails after ordinary damage adds Life cards to the defender''s hand is rejected. Variants: Dual/Triple Attack aggro, Critical pressure and a wider small-attacker board; include a non-forced lethal case where conserving resources is acceptable. Partial existing evidence: combat threshold/Strike cases and one search two-attacker lethal. The real three-attacker Life-to-hand search case remains a documented failure; no cross-deck pass. This benchmark starts planned. A pass requires a named fixture, deck/rules/policy revision and reviewed evidence; one generic case never passes all decks.','docs/arena-strategy-validation.md#ai-01'),
('ai-02','AI-02 — Avoidable loss and efficient defense','strategy','Objective: survive the declared attack sequence when legal defense exists, then minimize necessary card/energy expenditure within the fixture''s surviving lines. Acceptable actions may be block, counter, combo or battle activation; ties follow the real engine and a cheap defense that loses to the next attack is rejected. Variants: low-Life aggro, control with multiple counters and a development deck protecting its key base. Partial existing evidence: combat fixtures prove lethal blocking, cheapest sufficient combo and non-redundant counter in synthetic battles; missing cross-attack and real-deck defenses. This benchmark starts planned. A pass requires a named fixture, deck/rules/policy revision and reviewed evidence; one generic case never passes all decks.','docs/arena-strategy-validation.md#ai-02'),
('ai-03','AI-03 — Energy, colors and future payments','strategy','Objective: choose a legal development/payment sequence that preserves the fixture''s specified next-turn play or defensive payment. Acceptable actions retain the needed active colored sources without sacrificing a strictly better survival/lethal line; enumerate equivalent energy choices rather than require an arbitrary card ID. Variants: mono-color, multicolor/Energy-Exhaust and White Hidden/Revealed resources. Partial existing evidence: Main play/payment preserves a needed color in synthetic positions; missing real multicolor, White and future-turn variants. This benchmark starts planned. A pass requires a named fixture, deck/rules/policy revision and reviewed evidence; one generic case never passes all decks.','docs/arena-strategy-validation.md#ai-03'),
('ai-04','AI-04 — Card advantage and combo opportunity costs','strategy','Objective: spend a card or activation only when it changes the declared battle/board outcome or enables the fixture''s follow-up; preserve explicitly needed material/counter cards when an equivalent expendable card exists. Acceptable actions are cheapest sufficient outcome-equivalent lines, allowing printed draw/recovery value to change the ranking. Variants: aggro hand pressure, draw/control engines and fusion/evolution material hands. Partial existing evidence: efficient synthetic combos and least-value required discards; missing printed-effect opportunity-cost variants. This benchmark starts planned. A pass requires a named fixture, deck/rules/policy revision and reviewed evidence; one generic case never passes all decks.','docs/arena-strategy-validation.md#ai-04'),
('ai-05','AI-05 — Critical versus ordinary attack order','strategy','Objective: choose an attack order that attains the fixture''s proven damage/lethal result against the declared legal defenses, accounting for Critical sending Life to Drop versus ordinary damage replenishing hand. Acceptable actions include every equally effective first attack; Critical-first is not a universal rule. Variants: mixed Critical/ordinary attackers, multiple attacks and blockers/Strike damage. Partial existing evidence: combat values Critical/Double Strike; search explicitly omits Life-to-hand replenishment. Missing exact real-deck attack-order cases. This benchmark starts planned. A pass requires a named fixture, deck/rules/policy revision and reviewed evidence; one generic case never passes all decks.','docs/arena-strategy-validation.md#ai-05'),
('ai-06','AI-06 — Development sequencing and curve','strategy','Objective: choose a feasible turn sequence that achieves the fixture''s declared board/resource milestone while retaining required defense, instead of merely playing the highest-cost card. Acceptable actions are equivalent legal orders with the measured milestone and no avoidable survival loss. Variants: low-curve aggro, Unison/marker development and resource-dependent control; include pass/end-turn when every play is dominated. Partial existing evidence: affordable development, favorable attack, endMain and free-activation termination; missing multi-effect printed development sequences. This benchmark starts planned. A pass requires a named fixture, deck/rules/policy revision and reviewed evidence; one generic case never passes all decks.','docs/arena-strategy-validation.md#ai-06'),
('ai-07','AI-07 — Fusion and evolution material planning','strategy','Objective: preserve, find or develop the printed eligible materials/base so the declared next legal Fusion/Evolve line remains available, unless immediate survival or forced lethal dominates it. Acceptable actions use exact printed names, colors, power/areas and payment requirements; compare alternative bases/materials by resulting board and retained resources. Variants: Union-Fusion, Union-Potara and Evolve/EX-Evolve. Existing rule-family evidence can establish legal ingredients but is not a strategic planning proof; named cross-deck material decisions are missing. This benchmark starts planned. A pass requires a named fixture, deck/rules/policy revision and reviewed evidence; one generic case never passes all decks.','docs/arena-strategy-validation.md#ai-07'),
('ai-08','AI-08 — Removal and control target selection','strategy','Objective: remove or disable the fixture''s threat that changes the declared survival/board objective, respecting targeting protection and legal effect scope. Acceptable actions include all outcome-equivalent targets or decline when removal has no benefit; raw power alone is insufficient when a smaller engine/blocker determines the result. Variants: aggro removing a blocker, control breaking an engine and protected versus unprotected targets. Partial existing evidence: optional/required synthetic picks choose higher-value targets and useful printed modes; missing effect-aware real-target comparisons. This benchmark starts planned. A pass requires a named fixture, deck/rules/policy revision and reviewed evidence; one generic case never passes all decks.','docs/arena-strategy-validation.md#ai-08'),
('ai-09','AI-09 — Recursion and finite resource loops','strategy','Objective: choose an eligible recovered/replayed card that enables the fixture''s declared defense/development line, with printed limits and net costs accounted for. Acceptable actions finish a beneficial bounded cycle or decline/end when repeated recovery cannot improve the objective; infinite or unproductive activation is rejected. Variants: Desire recovery, Revive/Swap and Extra/Drop recursion. Partial existing evidence: priced Auto/mode/replacement choices and Main cycle guard; missing real recursive engine value and timing benchmarks. This benchmark starts planned. A pass requires a named fixture, deck/rules/policy revision and reviewed evidence; one generic case never passes all decks.','docs/arena-strategy-validation.md#ai-09'),
('ai-10','AI-10 — Optional payment and deliberate decline','strategy','Objective: pay an optional price only when its declared benefit justifies losing the resources needed for the fixture''s other legal objective; otherwise decline without spending. Acceptable actions include every full-payment line with equivalent benefit and resource retention, or decline; partial exact-count payment never qualifies. Variants: optional hand/Warp prices, Life-taking choices and Hidden/Revealed energy costs. Partial existing evidence: synthetic paid Auto, optional Life pick and Offering choices; exact payment rule proofs do not establish real-card value decisions. This benchmark starts planned. A pass requires a named fixture, deck/rules/policy revision and reviewed evidence; one generic case never passes all decks.','docs/arena-strategy-validation.md#ai-10'),
('ai-11','AI-11 — Robust decisions under hidden information','strategy','Objective: make the same choice for identical permitted observations/policy RNG across hidden-state permutations, while choosing within the fixture''s declared public-information risk objective. Acceptable actions are predeclared safe/expected-value alternatives under an explicit response distribution; no action is rewarded for exploiting an unseen card identity. Variants: unknown combo hands, counters and unseen deck/Life order across aggro/control/material decks. Existing suites prove hidden-permutation invariance in sampled generic positions; missing archetype-specific risk decisions and calibrated distributions. This benchmark starts planned. A pass requires a named fixture, deck/rules/policy revision and reviewed evidence; one generic case never passes all decks.','docs/arena-strategy-validation.md#ai-11'),
('ai-12','AI-12 — Adapt pressure, control and long-game plans','strategy','Objective: select the fixture''s demonstrated short- or long-horizon plan from visible race, resources and threats: pressure when delaying loses the race, stabilize when racing loses, conserve/recur when that enables the declared later win. Acceptable actions come from reviewed finite continuations with explicit horizon and response assumptions; ambiguous choices are diagnostic, not forced failures. Variants: aggro mirror, aggro versus control and recursion/material versus resource denial. Generic affordable-play/efficient-battle proofs do not establish plan adaptation; all named cross-archetype cases are missing. This benchmark starts planned. A pass requires a named fixture, deck/rules/policy revision and reviewed evidence; one generic case never passes all decks.','docs/arena-strategy-validation.md#ai-12')
