CREATE TABLE "arena_testing_decks" (
	"id" text PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"category" text NOT NULL,
	"first_wave" boolean DEFAULT false NOT NULL,
	"description" text NOT NULL,
	"source" text NOT NULL,
	"linked_deck_id" integer,
	"status" text DEFAULT 'planned' NOT NULL,
	"note" text DEFAULT '' NOT NULL,
	"evidence" text DEFAULT '' NOT NULL,
	"version" integer DEFAULT 0 NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "arena_testing_decks_status_check" CHECK ("arena_testing_decks"."status" in ('planned','in_progress','blocked','failed','passed')),
	CONSTRAINT "arena_testing_decks_version_check" CHECK ("arena_testing_decks"."version" >= 0)
);
--> statement-breakpoint
CREATE TABLE "arena_testing_matches" (
	"id" serial PRIMARY KEY NOT NULL,
	"request_id" text NOT NULL,
	"fingerprint" text NOT NULL,
	"p1_deck_id" text NOT NULL,
	"p2_deck_id" text NOT NULL,
	"p1" jsonb NOT NULL,
	"p2" jsonb NOT NULL,
	"outcome" text NOT NULL,
	"winner" text,
	"seed" integer,
	"rules_revision" text DEFAULT '' NOT NULL,
	"evidence" text DEFAULT '' NOT NULL,
	"note" text DEFAULT '' NOT NULL,
	"reported_cost_micros" integer,
	"recorded_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "arena_testing_matches_request_id_unique" UNIQUE("request_id"),
	CONSTRAINT "arena_testing_matches_outcome_check" CHECK ("arena_testing_matches"."outcome" in ('win','draw','interrupted','abandoned','limit')),
	CONSTRAINT "arena_testing_matches_winner_check" CHECK (("arena_testing_matches"."outcome" = 'win' and "arena_testing_matches"."winner" is not null and "arena_testing_matches"."winner" in ('p1','p2')) or ("arena_testing_matches"."outcome" <> 'win' and "arena_testing_matches"."winner" is null)),
	CONSTRAINT "arena_testing_matches_cost_check" CHECK ("arena_testing_matches"."reported_cost_micros" >= 0),
	CONSTRAINT "arena_testing_matches_evidence_check" CHECK ("arena_testing_matches"."outcome" not in ('win','draw') or length(trim("arena_testing_matches"."evidence")) > 0)
);
