	"version" integer DEFAULT 0 NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "arena_testing_scenarios_status_check" CHECK ("arena_testing_scenarios"."status" in ('planned','in_progress','blocked','failed','passed')),
	CONSTRAINT "arena_testing_scenarios_version_check" CHECK ("arena_testing_scenarios"."version" >= 0)
);
